 t=phi+i*math.pi/2;P=R*np.c_[np.cos(t),np.sin(t)];B=np.array([.00688,0])+r*np.c_[np.cos(t+delta),np.sin(t+delta)];V=B-P;D=np.linalg.norm(V,axis=1);k=(h*h+D*D-L*L)/(2*h*D);al=np.arctan2(V[:,1],V[:,0]);neu=t-math.pi/2;can=np.array([al+np.arccos(k),al-np.arccos(k)]);pitch=(can-neu+math.pi)%(2*math.pi)-math.pi;p=np.take_along_axis(pitch,np.argmin(abs(pitch),axis=0)[None,:],axis=0)[0];angle=neu+p;A=P+h*np.c_[np.cos(angle),np.sin(angle)];u=(B-A)/L;arm=A-P;lever=arm[:,0]*u[:,1]-arm[:,1]*u[:,0];second=(np.roll(p,-1)-2*p+np.roll(p,1))/(2*math.pi/N)**2;M=J*omega**2*second;F=M/lever;force=-F[:,None]*u;net+=force;bc=B-[.00688,0];torque+=bc[:,0]*force[:,1]-bc[:,1]*force[:,0];maxrod=max(maxrod,float(abs(F).max()));maxhinge=max(maxhinge,float(abs(M).max()))
